const allowedFields = new Set(['schema_version', 'event_id', 'package_id', 'event_type', 'occurred_at', 'source', 'idempotency_key', 'evidence_ref', 'correction_of', 'corrected_event_type', 'payload_version']);
const requiredFields = ['schema_version', 'event_id', 'package_id', 'event_type', 'occurred_at', 'source', 'idempotency_key', 'payload_version'];
const forbiddenField = /credential|token|password|secret/i;
const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const outcomeTypes = new Set(['drafted', 'approved', 'submitted', 'interview', 'rejected', 'offer', 'withdrawn', 'correction']);
const correctionTypes = new Set(['drafted', 'approved', 'submitted', 'interview', 'rejected', 'offer', 'withdrawn']);

return $input.all().map((item) => {
  const payload = item.json.body ?? item.json;
  const validObject = payload !== null && typeof payload === 'object' && !Array.isArray(payload);
  const keys = validObject ? Object.keys(payload) : [];
  const unknown = keys.filter((key) => !allowedFields.has(key) || forbiddenField.test(key));
  const missing = validObject ? requiredFields.filter((key) => !(key in payload)) : [...requiredFields];
  const validVersions = validObject && payload.schema_version === '1.0.0' && payload.payload_version === '1.0.0';
  const validText = validObject && requiredFields.every((key) => typeof payload[key] === 'string' && payload[key].trim());
  const validType = validObject && outcomeTypes.has(payload.event_type);
  const validEventId = validObject && typeof payload.event_id === 'string' && uuidPattern.test(payload.event_id);
  const validOccurredAt = validObject && typeof payload.occurred_at === 'string' && /(?:Z|[+-]\d{2}:\d{2})$/.test(payload.occurred_at) && !Number.isNaN(Date.parse(payload.occurred_at));
  const optionalText = (value) => value === null || (typeof value === 'string' && value.trim());
  const validCorrection = validObject && (payload.event_type === 'correction'
    ? typeof payload.evidence_ref === 'string' && payload.evidence_ref.trim() && typeof payload.correction_of === 'string' && uuidPattern.test(payload.correction_of) && correctionTypes.has(payload.corrected_event_type)
    : payload.correction_of === null && payload.corrected_event_type === null && optionalText(payload.evidence_ref));
  if (!validObject || unknown.length || missing.length || !validVersions || !validText || !validType || !validEventId || !validOccurredAt || !validCorrection) {
    return { json: { route_state: 'quarantine', reason: 'invalid_outcome_event', received_type: Array.isArray(payload) ? 'array' : typeof payload, rejected_fields: unknown.sort(), external_sends: 0 } };
  }
  return { json: { route_state: 'accepted', event: payload } };
});

const state = $getWorkflowStaticData('global');
state.outcomeEventByIdempotencyKey ??= {};

return $input.all().map((item) => {
  const event = item.json.event;
  const idempotencyKey = event.idempotency_key;
  const canonical = Object.keys(event).sort().reduce((result, key) => { result[key] = event[key]; return result; }, {});
  const fingerprint = JSON.stringify(canonical);
  const previous = state.outcomeEventByIdempotencyKey[idempotencyKey];
  if (previous === fingerprint) {
    return { json: { route_state: 'replay_noop', event, fingerprint, external_sends: 0 } };
  }
  if (previous !== undefined) {
    return { json: { route_state: 'quarantine', reason: 'idempotency_conflict', event, external_sends: 0 } };
  }
  return { json: { route_state: 'accepted', event, fingerprint, external_sends: 0 } };
});

const maxAttempts = 3;
return $input.all().map((item) => ({
  json: {
    ...item.json,
    route: 'operational_placeholder',
    external_sends: 0,
    retry_policy: { max_attempts: maxAttempts, dead_letter: 'manual_review' },
    live_import_runtime: 'UNVERIFIED'
  }
}));

const state = $getWorkflowStaticData('global');
state.outcomeEventByIdempotencyKey ??= {};

return $input.all().map((item) => {
  const key = item.json.event.idempotency_key;
  state.outcomeEventByIdempotencyKey[key] = item.json.fingerprint;
  return { json: { ...item.json, route_state: 'processed' } };
});

return $input.all().map((item) => {
  if (item.json.route_state === 'replay_noop') {
    return { json: { route_state: 'replay_noop', route: 'no_op', event_id: item.json.event.event_id, package_id: item.json.event.package_id, idempotency_key: item.json.event.idempotency_key, external_sends: 0, live_import_runtime: 'UNVERIFIED' } };
  }
  const event = item.json.event ?? {};
  return { json: { route_state: 'quarantine', route: 'manual_review', reason: item.json.reason ?? 'invalid_outcome_event', rejected_fields: item.json.rejected_fields ?? [], received_type: item.json.received_type ?? 'object', event_id: typeof event.event_id === 'string' ? event.event_id : null, package_id: typeof event.package_id === 'string' ? event.package_id : null, idempotency_key: typeof event.idempotency_key === 'string' ? event.idempotency_key : null, dead_letter: true, external_sends: 0, live_import_runtime: 'UNVERIFIED' } };
});
